contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Try depositing some amount and then attempting to Collect; ensure that when Collect does not revert,
    // the stored balance observed via the public getter never increases.
    function run(uint depositAmt, uint collectAmt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmt, "insufficient test balance");

        // If c is not yet initialized, try to set MinSum to 0 so Collect may succeed; ignore failure.
        c.SetMinSum(0); bool __rev0 = __ESBMC_reverted(); if (__rev0) {} else {
        }

        // Deposit funds into c from this contract
        require(address(this).balance >= depositAmt, "not enough balance for deposit");
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // Read balance before attempting Collect
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // Attempt Collect and record whether it reverted
        bool didRevert;
        c.Collect(collectAmt); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            didRevert = true;
        } else {
            didRevert = false;
        }

        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // General invariant: if Collect succeeded (didRevert == false) then the stored balance did not increase.
        // We express this as afterBal <= beforeBal, and additionally if Collect succeeded and collectAmt > 0
        // then afterBal < beforeBal or collectAmt was zero; but to keep it general we assert non-increase.
        assert(didRevert || afterBal <= beforeBal);
    }

    // allow receiving Ether so that the test harness can fund this contract
    receive() external payable {}
}

