import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 depositAmt, uint256 collectAmt) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmt);
        try c.SetMinSum(0) {
        } catch {}
        vm.assume(address(this).balance >= depositAmt);
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        bool didRevert;
        try c.Collect(collectAmt) {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(didRevert || afterBal <= beforeBal);
    }

    function testFuzz_run(uint256 depositAmt, uint256 collectAmt) public {
        _run(depositAmt, collectAmt);
    }

    receive() external payable {}
}
